const dashboardHTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"color-scheme\" content=\"light\">\n<title>CI Radar</title>\n<link rel=\"stylesheet\" href=\"/assets/dashboard.css\">\n</head>\n<body>\n<div class=\"app-shell\">\n<aside class=\"sidebar\">\n<div class=\"wordmark\">\n<strong>CI Radar</strong>\n<span>CI operations</span>\n</div>\n<nav class=\"nav\" aria-label=\"Dashboard sections\">\n<button type=\"button\" data-tab=\"overview\" class=\"active\"><span>Overview</span><b id=\"nav-overview-count\"></b></button>\n<button type=\"button\" data-tab=\"incidents\"><span>Incidents</span><b id=\"nav-incident-count\"></b></button>\n<button type=\"button\" data-tab=\"diagnoses\"><span>Diagnoses</span><b id=\"nav-diagnosis-count\"></b></button>\n<button type=\"button\" data-tab=\"tests\"><span>Tests</span><b id=\"nav-test-count\"></b></button>\n<button type=\"button\" data-tab=\"operations\"><span>Operations</span><b id=\"nav-provider-count\"></b></button>\n</nav>\n<details id=\"session-panel\" class=\"session-panel\">\n<summary>Session</summary>\n<div class=\"session-fields\">\n<label for=\"tenant\">Tenant</label>\n<input id=\"tenant\" autocomplete=\"organization\" value=\"default\">\n<label for=\"token\">Admin token or API key</label>\n<input id=\"token\" type=\"password\" autocomplete=\"off\">\n<div class=\"session-actions\">\n<button id=\"secure-login\" type=\"button\" class=\"primary\">Sign in</button>\n<button id=\"sso-login\" type=\"button\">SSO</button>\n</div>\n<button id=\"logout\" type=\"button\" class=\"text-button\">Sign out</button>\n</div>\n</details>\n<div class=\"sidebar-foot\">\n<span id=\"connection-state\" class=\"connection-state\">Connecting</span>\n<a href=\"/source\">Source</a>\n</div>\n</aside>\n<div class=\"workspace\">\n<header class=\"page-header\">\n<div>\n<h1 id=\"page-title\">Overview</h1>\n<p id=\"page-description\">CI health across the selected period.</p>\n</div>\n<div class=\"page-actions\">\n<label class=\"field-inline\" for=\"range\"><span>Period</span><select id=\"range\"><option value=\"24h\">24 hours</option><option value=\"168h\" selected>7 days</option><option value=\"720h\">30 days</option><option value=\"2160h\">90 days</option><option value=\"4320h\">180 days</option><option value=\"8760h\">365 days</option></select></label>\n<button id=\"refresh\" type=\"button\">Reload</button>\n</div>\n</header>\n<div class=\"status-row\"><span id=\"updated-at\">Not loaded</span></div>\n<div id=\"error\" role=\"alert\" aria-live=\"polite\"></div>\n<main>\n<section id=\"overview\" class=\"view active\">\n<section id=\"cards\" class=\"metric-strip\" aria-label=\"Summary metrics\"></section>\n<section class=\"chart-grid\">\n<article class=\"panel chart-panel\"><header class=\"panel-header\"><div><h2>Diagnoses</h2><p>Failures analyzed per day</p></div></header><div id=\"analysistrend\" class=\"svg-chart\"></div></article>\n<article class=\"panel chart-panel\"><header class=\"panel-header\"><div><h2>Incidents</h2><p>New incidents per day</p></div></header><div id=\"incidenttrend\" class=\"svg-chart\"></div></article>\n<article class=\"panel chart-panel\"><header class=\"panel-header\"><div><h2>Test failures</h2><p>Recorded failures per day</p></div></header><div id=\"testtrend\" class=\"svg-chart\"></div></article>\n<article class=\"panel chart-panel\"><header class=\"panel-header\"><div><h2>CI cost</h2><p>Estimated spend per day</p></div></header><div id=\"costtrend\" class=\"svg-chart\"></div></article>\n</section>\n<section class=\"content-grid\">\n<article class=\"panel\"><header class=\"panel-header\"><div><h2>DORA metrics</h2><p>Selected period</p></div></header><div id=\"dora\" class=\"metric-list\"></div></article>\n<article class=\"panel\"><header class=\"panel-header\"><div><h2>Failure categories</h2><p>Diagnosis volume</p></div></header><div id=\"category-bars\" class=\"category-bars\"></div></article>\n</section>\n<article class=\"panel\"><header class=\"panel-header\"><div><h2>Active incidents</h2><p>Highest priority unresolved work</p></div><button type=\"button\" data-tab-jump=\"incidents\">View all</button></header><div class=\"table-wrap\"><table><thead><tr><th>Incident</th><th>State</th><th>Impact</th><th></th></tr></thead><tbody id=\"incident-preview\"></tbody></table></div></article>\n</section>\n<section id=\"incidents\" class=\"view\">\n<article class=\"panel\">\n<header class=\"panel-header table-header\"><div><h2>Incidents</h2><p id=\"incident-count\"></p></div><div class=\"filters\"><input id=\"incident-search\" type=\"search\" placeholder=\"Search incidents\"><select id=\"incident-state\"><option value=\"\">All states</option><option value=\"open\">Open</option><option value=\"acknowledged\">Acknowledged</option><option value=\"resolved\">Resolved</option></select><select id=\"incident-severity\"><option value=\"\">All severities</option><option value=\"critical\">Critical</option><option value=\"high\">High</option><option value=\"medium\">Medium</option><option value=\"low\">Low</option></select></div></header>\n<div class=\"table-wrap\"><table><thead><tr><th>Incident</th><th>Provider</th><th>State</th><th>Repos</th><th>Events</th><th>Last seen</th><th></th></tr></thead><tbody id=\"incident-table\"></tbody></table></div>\n</article>\n</section>\n<section id=\"diagnoses\" class=\"view\">\n<article class=\"panel\">\n<header class=\"panel-header table-header\"><div><h2>Diagnoses</h2><p id=\"analysis-count\"></p></div><div class=\"filters\"><input id=\"analysis-search\" type=\"search\" placeholder=\"Search diagnoses\"><select id=\"analysis-attribution\"><option value=\"\">All attributions</option><option value=\"EXTERNAL\">External</option><option value=\"CODE\">Code</option><option value=\"MIXED\">Mixed</option><option value=\"TOOLCHAIN\">Toolchain</option><option value=\"UNKNOWN\">Unknown</option></select><select id=\"analysis-category\"><option value=\"\">All categories</option></select><select id=\"analysis-provider\"><option value=\"\">All providers</option></select></div></header>\n<div class=\"table-wrap\"><table><thead><tr><th>Time</th><th>Repository / job</th><th>Decision</th><th>Summary</th><th>Evidence</th><th>Feedback</th></tr></thead><tbody id=\"analysis-table\"></tbody></table></div>\n</article>\n</section>\n<section id=\"tests\" class=\"view\">\n<article class=\"panel\">\n<header class=\"panel-header table-header\"><div><h2>Test intelligence</h2><p id=\"test-count\"></p></div><div class=\"filters\"><input id=\"test-search\" type=\"search\" placeholder=\"Search tests\"><select id=\"test-state\"><option value=\"\">All states</option><option value=\"flaky\">Flaky</option><option value=\"consistently_failing\">Consistently failing</option><option value=\"stable\">Stable</option><option value=\"suspected_flaky\">Suspected flaky</option><option value=\"warming_up\">Warming up</option><option value=\"not_executed\">Not executed</option><option value=\"mixed\">Mixed</option></select><select id=\"test-cause\"><option value=\"\">All causes</option><option value=\"timing\">Timing</option><option value=\"selector\">Selector</option><option value=\"network\">Network</option><option value=\"environment\">Environment</option><option value=\"resource\">Resource</option><option value=\"order_state\">Order/state</option><option value=\"concurrency\">Concurrency</option><option value=\"data\">Data</option><option value=\"unknown\">Unknown</option></select></div></header>\n<div class=\"table-wrap\"><table><thead><tr><th>Test</th><th>Repository</th><th>History</th><th>Flake score</th><th>Likely cause</th><th>State</th><th></th></tr></thead><tbody id=\"test-table\"></tbody></table></div>\n</article>\n</section>\n<section id=\"operations\" class=\"view\">\n<section class=\"content-grid operations-grid\">\n<article class=\"panel\"><header class=\"panel-header\"><div><h2>Repository routing</h2><p>Ownership and notification targets</p></div></header><div class=\"table-wrap\"><table><thead><tr><th>Repository</th><th>Team</th><th>Criticality</th><th>Channels</th></tr></thead><tbody id=\"repositories\"></tbody></table></div></article>\n<article class=\"panel\"><header class=\"panel-header\"><div><h2>Notification deliveries</h2><p>Latest attempts</p></div></header><div class=\"table-wrap\"><table><thead><tr><th>Channel</th><th>Status</th><th>Attempts</th><th>Last error</th></tr></thead><tbody id=\"deliveries\"></tbody></table></div></article>\n</section>\n<article class=\"panel\"><header class=\"panel-header\"><div><h2>Connected providers</h2><p id=\"provider-count\"></p></div></header><div id=\"providers\" class=\"provider-list\"></div></article>\n</section>\n</main>\n</div>\n</div>\n<aside id=\"drawer\" class=\"drawer\" aria-hidden=\"true\"><header class=\"drawer-head\"><div><span id=\"drawer-kind\"></span><h2 id=\"drawer-title\"></h2></div><button id=\"drawer-close\" type=\"button\" aria-label=\"Close\">Close</button></header><div id=\"drawer-body\" class=\"drawer-body\"></div></aside>\n<div id=\"backdrop\" class=\"backdrop\" hidden></div>\n<dialog id=\"action-dialog\" class=\"action-dialog\">\n<form id=\"action-form\">\n<header><div><span id=\"action-kind\"></span><h2 id=\"action-title\"></h2></div><button id=\"action-close\" type=\"button\">Close</button></header>\n<p id=\"action-description\"></p>\n<div id=\"action-fields\" class=\"action-fields\"></div>\n<footer><button id=\"action-cancel\" type=\"button\">Cancel</button><button id=\"action-submit\" type=\"submit\" class=\"primary\">Save</button></footer>\n</form>\n</dialog>\n<script src=\"/assets/dashboard.js\" defer></script>\n</body>\n</html>\n"

const dashboardCSS = ":root{\n color-scheme:light;\n --canvas:#f6f8fa;\n --surface:#ffffff;\n --surface-subtle:#f6f8fa;\n --surface-hover:#f3f4f6;\n --border:#d0d7de;\n --border-muted:#d8dee4;\n --text:#1f2328;\n --muted:#656d76;\n --faint:#8c959f;\n --accent:#0969da;\n --accent-hover:#0757b5;\n --success:#1a7f37;\n --warning:#9a6700;\n --danger:#cf222e;\n --purple:#8250df;\n --sidebar:232px;\n}\n*{box-sizing:border-box}\nhtml{background:var(--canvas)}\nbody{margin:0;min-width:320px;background:var(--canvas);color:var(--text);font:13px/1.45 -apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\nbutton,input,select{font:inherit}\nbutton,input,select{border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--text)}\nbutton{min-height:32px;padding:5px 12px;cursor:pointer;font-weight:600}\nbutton:hover{background:var(--surface-hover)}\nbutton:focus-visible,input:focus,select:focus,summary:focus-visible{outline:2px solid rgba(9,105,218,.35);outline-offset:2px}\nbutton.primary{border-color:var(--accent);background:var(--accent);color:#fff}\nbutton.primary:hover{background:var(--accent-hover)}\nbutton.danger{color:var(--danger)}\nbutton.text-button{border:0;background:transparent;color:var(--muted);padding-inline:0;text-align:left}\ninput,select{height:32px;padding:5px 9px}\ninput::placeholder{color:var(--faint)}\na{color:var(--accent);text-decoration:none}\na:hover{text-decoration:underline}\n.app-shell{display:grid;grid-template-columns:var(--sidebar) minmax(0,1fr);min-height:100vh}\n.sidebar{position:sticky;top:0;height:100vh;display:flex;flex-direction:column;border-right:1px solid var(--border);background:var(--surface);padding:18px 12px 12px}\n.wordmark{display:flex;flex-direction:column;padding:0 10px 18px;border-bottom:1px solid var(--border-muted)}\n.wordmark strong{font-size:16px;letter-spacing:-.2px}\n.wordmark span{margin-top:2px;color:var(--muted);font-size:12px}\n.nav{display:grid;gap:2px;padding:14px 0}\n.nav button{display:flex;align-items:center;justify-content:space-between;width:100%;border:0;background:transparent;color:var(--muted);font-weight:500;text-align:left}\n.nav button:hover{background:var(--surface-hover);color:var(--text)}\n.nav button.active{background:#ddf4ff;color:#0550ae;font-weight:600}\n.nav button b{min-width:18px;color:inherit;font-size:11px;text-align:right}\n.session-panel{margin-top:auto;border-top:1px solid var(--border-muted);padding-top:12px}\n.session-panel summary{cursor:pointer;color:var(--muted);font-weight:600;padding:6px 8px}\n.session-fields{display:grid;gap:7px;padding:8px}\n.session-fields label{color:var(--muted);font-size:12px}\n.session-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:3px}\n.sidebar-foot{display:flex;align-items:center;justify-content:space-between;padding:12px 8px 0;color:var(--muted);font-size:12px}\n.connection-state{display:inline-flex;align-items:center;gap:6px}\n.connection-state::before{content:\"\";width:7px;height:7px;border-radius:50%;background:var(--warning)}\n.connection-state.online::before{background:var(--success)}\n.connection-state.offline::before{background:var(--danger)}\n.workspace{min-width:0}\n.page-header{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px 28px 14px;background:var(--surface);border-bottom:1px solid var(--border)}\n.page-header h1{margin:0;font-size:20px;line-height:1.25;letter-spacing:-.25px}\n.page-header p{margin:4px 0 0;color:var(--muted)}\n.page-actions{display:flex;align-items:flex-end;gap:8px}\n.field-inline{display:flex;align-items:center;gap:8px;color:var(--muted)}\n.status-row{display:flex;justify-content:flex-end;padding:7px 28px;color:var(--muted);font-size:12px;background:var(--surface);border-bottom:1px solid var(--border-muted)}\n#error{display:none;margin:16px 28px 0;padding:10px 12px;border:1px solid #ff818266;border-radius:6px;background:#ffebe9;color:#82071e;font-weight:600}\n#error:not(:empty){display:block}\nmain{max-width:1680px;padding:18px 28px 42px}\n.view{display:none}\n.view.active{display:grid;gap:16px}\n.metric-strip{display:grid;grid-template-columns:repeat(8,minmax(110px,1fr));border:1px solid var(--border);border-radius:6px;background:var(--surface);overflow:hidden}\n.metric{min-width:0;padding:14px 16px;border-right:1px solid var(--border-muted)}\n.metric:last-child{border-right:0}\n.metric span{display:block;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.metric b{display:block;margin-top:5px;font-size:20px;line-height:1.2;font-weight:600;font-variant-numeric:tabular-nums}\n.metric small{display:block;margin-top:4px;color:var(--faint);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.panel{min-width:0;border:1px solid var(--border);border-radius:6px;background:var(--surface)}\n.panel-header{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:14px 16px;border-bottom:1px solid var(--border-muted)}\n.panel-header h2{margin:0;font-size:14px;line-height:1.3}\n.panel-header p{margin:3px 0 0;color:var(--muted);font-size:12px}\n.chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}\n.chart-panel .svg-chart{padding:12px 14px 6px}\n.svg-chart{min-height:210px}\n.svg-chart svg{display:block;width:100%;height:210px;overflow:visible}\n.svg-chart text{fill:var(--muted);font-size:11px}\n.svg-chart .gridline{stroke:var(--border-muted);stroke-width:1}\n.svg-chart .line{fill:none;stroke:var(--accent);stroke-width:2;stroke-linejoin:round;stroke-linecap:round}\n.svg-chart circle{fill:var(--surface);stroke:var(--accent);stroke-width:2}\n.chart-empty,.empty{padding:30px;color:var(--muted);text-align:center}\n.content-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.metric-list{display:grid;grid-template-columns:minmax(0,1fr) auto;padding:4px 16px}\n.metric-list span,.metric-list b{padding:11px 0;border-bottom:1px solid var(--border-muted)}\n.metric-list span:nth-last-child(-n+2),.metric-list b:nth-last-child(-n+2){border-bottom:0}\n.metric-list span{color:var(--muted)}\n.metric-list b{text-align:right;font-variant-numeric:tabular-nums}\n.category-bars{display:grid;gap:12px;padding:15px 16px}\n.category-bars>div{display:grid;grid-template-columns:minmax(100px,1fr) minmax(120px,2fr) 40px;align-items:center;gap:12px}\n.category-bars span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}\n.category-bars b{text-align:right;font-variant-numeric:tabular-nums}\nprogress{width:100%;height:6px;border:0;border-radius:3px;background:#eaeef2;overflow:hidden}\nprogress::-webkit-progress-bar{background:#eaeef2}\nprogress::-webkit-progress-value{background:var(--accent)}\nprogress::-moz-progress-bar{background:var(--accent)}\n.score{display:flex;align-items:center;gap:8px;font-variant-numeric:tabular-nums}\n.score span{min-width:28px;text-align:right}\n.score progress{width:88px}\n.table-header{align-items:center}\n.filters{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:7px}\n.filters input{min-width:210px}\n.table-wrap{max-width:100%;overflow:auto}\ntable{width:100%;border-collapse:collapse;text-align:left}\nth,td{padding:10px 12px;border-bottom:1px solid var(--border-muted);vertical-align:middle}\nth{position:sticky;top:0;z-index:1;background:var(--surface-subtle);color:var(--muted);font-size:12px;font-weight:600;white-space:nowrap}\ntbody tr:last-child td{border-bottom:0}\ntbody tr[data-open]{cursor:pointer}\ntbody tr[data-open]:hover{background:#f6f8fa}\ntd b{font-weight:600}\ntd small{display:block;margin-top:2px;color:var(--muted);max-width:520px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\ntd.summary{min-width:280px;max-width:520px}\ntd.actions{white-space:nowrap;text-align:right}\n.compact{min-height:26px;padding:2px 8px;margin-left:5px;font-size:12px;font-weight:500}\n.tag{display:inline-flex;align-items:center;min-height:22px;padding:1px 7px;border:1px solid var(--border);border-radius:12px;background:var(--surface-subtle);color:var(--muted);font-size:12px;white-space:nowrap;text-transform:capitalize}\n.tag-open,.tag-critical,.tag-consistently_failing,.tag-failed,.tag-incorrect{border-color:#ff8182;color:var(--danger);background:#ffebe9}\n.tag-acknowledged,.tag-high,.tag-suspected_flaky,.tag-warning,.tag-partial{border-color:#d4a72c66;color:var(--warning);background:#fff8c5}\n.tag-resolved,.tag-stable,.tag-success,.tag-correct{border-color:#4ac26b66;color:var(--success);background:#dafbe1}\n.tag-code,.tag-external,.tag-flaky{border-color:#54aeff66;color:#0550ae;background:#ddf4ff}\n.tag-mixed,.tag-toolchain,.tag-warming_up{border-color:#a475f966;color:var(--purple);background:#fbefff}\n.provider-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:4px 16px}\n.provider-row{display:flex;align-items:center;gap:9px;padding:12px 0;border-bottom:1px solid var(--border-muted)}\n.provider-row:nth-last-child(-n+3){border-bottom:0}\n.provider-row::before{content:\"\";width:8px;height:8px;border-radius:50%;background:var(--success)}\n.provider-row small{display:block;color:var(--muted)}\n.drawer{position:fixed;top:0;right:0;z-index:30;width:min(620px,100vw);height:100vh;transform:translateX(100%);background:var(--surface);border-left:1px solid var(--border);transition:transform .15s ease;overflow:auto}\n.drawer.open{transform:translateX(0)}\n.drawer-head{position:sticky;top:0;z-index:2;display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:18px 20px;background:var(--surface);border-bottom:1px solid var(--border)}\n.drawer-head span,.action-dialog header span{display:block;color:var(--muted);font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.5px}\n.drawer-head h2,.action-dialog h2{margin:3px 0 0;font-size:17px;line-height:1.35}\n.drawer-body{padding:20px}\n.drawer-body h3{margin:24px 0 8px;font-size:13px}\n.drawer-body p{color:#3d444d}\n.drawer-body dl{display:grid;grid-template-columns:160px minmax(0,1fr);margin:0;border-top:1px solid var(--border-muted)}\n.drawer-body dt,.drawer-body dd{margin:0;padding:8px 0;border-bottom:1px solid var(--border-muted)}\n.drawer-body dt{color:var(--muted)}\n.drawer-body dd{word-break:break-word}\n.drawer-body pre{max-height:320px;overflow:auto;padding:12px;border:1px solid var(--border);border-radius:6px;background:var(--surface-subtle);white-space:pre-wrap;word-break:break-word;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}\n.evidence{padding-left:20px;color:#3d444d}\n.evidence li{margin:6px 0}\n.recommendation{padding:11px 0;border-bottom:1px solid var(--border-muted)}\n.recommendation header{display:flex;justify-content:space-between;gap:12px}\n.recommendation p{margin:5px 0}\n.recommendation small{color:var(--muted)}\n.drawer-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px;padding-top:16px;border-top:1px solid var(--border-muted)}\n.backdrop{position:fixed;inset:0;z-index:25;background:rgba(31,35,40,.35)}\n.action-dialog{width:min(500px,calc(100vw - 32px));padding:0;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text)}\n.action-dialog::backdrop{background:rgba(31,35,40,.45)}\n.action-dialog form>header{display:flex;justify-content:space-between;gap:16px;padding:16px 18px;border-bottom:1px solid var(--border)}\n.action-dialog form>p{margin:0;padding:14px 18px 0;color:var(--muted)}\n.action-fields{display:grid;gap:10px;padding:14px 18px 18px}\n.action-fields label{display:grid;gap:5px;color:var(--muted);font-size:12px}\n.action-fields textarea{min-height:86px;resize:vertical;border:1px solid var(--border);border-radius:6px;padding:8px;font:inherit;color:var(--text)}\n.action-dialog footer{display:flex;justify-content:flex-end;gap:8px;padding:12px 18px;border-top:1px solid var(--border);background:var(--surface-subtle)}\nbody.loading #refresh{cursor:wait;opacity:.65}\nbody.loading #updated-at::after{content:\" · loading\"}\n@media(max-width:1180px){\n .metric-strip{grid-template-columns:repeat(4,minmax(120px,1fr))}\n .metric:nth-child(4n){border-right:0}\n .metric:nth-child(-n+4){border-bottom:1px solid var(--border-muted)}\n .provider-list{grid-template-columns:repeat(2,minmax(0,1fr))}\n .provider-row:nth-last-child(-n+3){border-bottom:1px solid var(--border-muted)}\n .provider-row:nth-last-child(-n+2){border-bottom:0}\n}\n@media(max-width:900px){\n :root{--sidebar:188px}\n .chart-grid,.content-grid{grid-template-columns:1fr}\n .page-header{align-items:flex-start;flex-direction:column}\n .page-actions{width:100%;justify-content:flex-end}\n .table-header{align-items:flex-start;flex-direction:column}\n .filters{width:100%;justify-content:flex-start}\n .filters input{flex:1}\n .operations-grid{grid-template-columns:1fr}\n}\n@media(max-width:700px){\n .app-shell{display:block}\n .sidebar{position:static;width:100%;height:auto;padding:12px;border-right:0;border-bottom:1px solid var(--border)}\n .wordmark{padding-bottom:12px}\n .nav{grid-template-columns:repeat(5,minmax(0,1fr));padding:10px 0 0;overflow:auto}\n .nav button{justify-content:center;white-space:nowrap}\n .nav button b,.session-panel,.sidebar-foot{display:none}\n .page-header{padding:16px}\n .status-row{padding:7px 16px}\n main{padding:14px 12px 30px}\n #error{margin:12px 12px 0}\n .metric-strip{grid-template-columns:repeat(2,minmax(120px,1fr))}\n .metric:nth-child(2n){border-right:0}\n .metric:nth-child(-n+6){border-bottom:1px solid var(--border-muted)}\n .page-actions{justify-content:flex-start;flex-wrap:wrap}\n .field-inline span{display:none}\n .filters{display:grid;grid-template-columns:1fr 1fr}\n .filters input{grid-column:1/-1;min-width:0}\n .provider-list{grid-template-columns:1fr}\n .provider-row:nth-last-child(-n+2){border-bottom:1px solid var(--border-muted)}\n .provider-row:last-child{border-bottom:0}\n .drawer-body dl{grid-template-columns:1fr}\n .drawer-body dt{padding-bottom:0;border-bottom:0}\n .drawer-body dd{padding-top:3px}\n}\n"

const dashboardJS = "const $ = id => document.getElementById(id)\n\nconst state = {\n dashboard: null,\n repositories: [],\n deliveries: [],\n tests: [],\n analyses: [],\n incidents: [],\n providers: [],\n loading: false\n}\n\nconst pageMeta = {\n overview: ['Overview', 'CI health across the selected period.'],\n incidents: ['Incidents', 'Correlated failures that need ownership and resolution.'],\n diagnoses: ['Diagnoses', 'Evidence and attribution for analyzed CI failures.'],\n tests: ['Tests', 'History, instability and quarantine state.'],\n operations: ['Operations', 'Repository routing, delivery health and connected providers.']\n}\n\nlet actionContext = null\n\n$('tenant').value = sessionStorage.ciradarTenant || 'default'\n\nasync function api(path, options = {}) {\n const tenant = $('tenant').value.trim() || 'default'\n sessionStorage.ciradarTenant = tenant\n options.headers = {\n  ...(options.headers || {}),\n  'X-CI-Radar-Tenant': tenant,\n  'Content-Type': 'application/json'\n }\n const response = await fetch(path, options)\n if (!response.ok) {\n  const payload = await response.json().catch(() => ({ error: response.statusText }))\n  const error = new Error(payload.error || response.statusText)\n  error.status = response.status\n  throw error\n }\n return response.status === 204 ? null : response.json()\n}\n\nasync function secureLogin() {\n const token = $('token').value.trim()\n const tenant = $('tenant').value.trim() || 'default'\n if (!token) throw new Error('Enter an admin token or API key.')\n const response = await fetch('/auth/token', {\n  method: 'POST',\n  headers: { 'Content-Type': 'application/json' },\n  body: JSON.stringify({ token, tenant })\n })\n if (!response.ok) {\n  const payload = await response.json().catch(() => ({ error: response.statusText }))\n  throw new Error(payload.error || response.statusText)\n }\n $('token').value = ''\n $('session-panel')?.removeAttribute('open')\n await load(true)\n}\n\nfunction esc(value) {\n return String(value ?? '').replace(/[&<>\"']/g, character => ({\n  '&': '&amp;',\n  '<': '&lt;',\n  '>': '&gt;',\n  '\"': '&quot;',\n  \"'\": '&#39;'\n }[character]))\n}\n\nfunction slug(value) {\n return String(value || 'unknown').toLowerCase().replace(/[^a-z0-9_-]+/g, '_')\n}\n\nfunction text(value) {\n return String(value ?? '').toLowerCase()\n}\n\nfunction empty(columns, message) {\n return `<tr><td colspan=\"${columns}\" class=\"empty\">${esc(message)}</td></tr>`\n}\n\nfunction button(action, id, label, kind = '') {\n return `<button type=\"button\" class=\"compact ${esc(kind)}\" data-action=\"${esc(action)}\" data-id=\"${esc(id)}\">${esc(label)}</button>`\n}\n\nfunction fmtDate(value) {\n return value ? new Date(value).toLocaleString() : '—'\n}\n\nfunction pct(value) {\n return Math.max(0, Math.min(100, Math.round(Number(value) || 0)))\n}\n\nfunction evidenceValue(item) {\n const explicit = Number(item.evidence_strength)\n return explicit > 0 ? explicit : Math.abs(Number(item.score || item.externality_score || 0))\n}\n\nfunction externalityValue(item) {\n const explicit = Number(item.externality_score)\n return explicit !== 0 ? explicit : Number(item.score || 0)\n}\n\nfunction scoreBar(value) {\n const score = pct(value)\n return `<div class=\"score\"><span>${Number(value || 0).toFixed(0)}</span><progress max=\"100\" value=\"${score}\" aria-label=\"Score ${score} out of 100\"></progress></div>`\n}\n\nfunction pill(value) {\n return `<span class=\"tag tag-${slug(value)}\">${esc(String(value || 'unknown').replaceAll('_', ' '))}</span>`\n}\n\nfunction pairs(value) {\n return Object.entries(value || {}).sort((left, right) => Number(right[1]) - Number(left[1]))\n}\n\nfunction series(value) {\n return Object.entries(value || {}).sort((left, right) => left[0].localeCompare(right[0]))\n}\n\nfunction setConnection(label, mode) {\n const element = $('connection-state')\n element.textContent = label\n element.className = `connection-state ${mode || ''}`.trim()\n}\n\nfunction setLoading(loading) {\n state.loading = loading\n document.body.classList.toggle('loading', loading)\n $('refresh').disabled = loading\n}\n\nfunction setError(message = '') {\n $('error').textContent = message\n}\n\nfunction svgChart(id, data, unit = '') {\n const points = series(data)\n const container = $(id)\n if (!points.length) {\n  container.innerHTML = '<div class=\"chart-empty\">No data in this period.</div>'\n  return\n }\n const values = points.map(item => Number(item[1]) || 0)\n const maximum = Math.max(1, ...values)\n const minimum = Math.min(0, ...values)\n const width = 720\n const height = 210\n const horizontalPadding = 34\n const verticalPadding = 24\n const x = index => horizontalPadding + (width - horizontalPadding * 2) * (points.length === 1 ? 0.5 : index / (points.length - 1))\n const y = value => height - verticalPadding - (height - verticalPadding * 2) * (value - minimum) / (maximum - minimum || 1)\n const polyline = points.map((item, index) => `${x(index)},${y(values[index])}`).join(' ')\n const grid = [0, 0.5, 1].map(position => {\n  const gridY = verticalPadding + (height - verticalPadding * 2) * position\n  return `<line class=\"gridline\" x1=\"${horizontalPadding}\" y1=\"${gridY}\" x2=\"${width - horizontalPadding}\" y2=\"${gridY}\"></line>`\n }).join('')\n const circles = points.map((item, index) => `<circle cx=\"${x(index)}\" cy=\"${y(values[index])}\" r=\"3\"><title>${esc(item[0])}: ${values[index].toFixed(unit ? 2 : 0)} ${esc(unit)}</title></circle>`).join('')\n const labelPoints = [points[0], points[Math.floor((points.length - 1) / 2)], points[points.length - 1]].filter((item, index, array) => array.findIndex(other => other[0] === item[0]) === index)\n const labels = labelPoints.map(item => {\n  const index = points.findIndex(point => point[0] === item[0])\n  return `<text x=\"${x(index)}\" y=\"${height - 4}\" text-anchor=\"middle\">${esc(item[0].slice(5))}</text>`\n }).join('')\n container.innerHTML = `<svg viewBox=\"0 0 ${width} ${height}\" role=\"img\">${grid}<polyline class=\"line\" points=\"${polyline}\"></polyline>${circles}${labels}</svg>`\n}\n\nfunction renderCards(dashboard) {\n const feedback = dashboard.diagnosis_feedback || {}\n const usage = dashboard.usage || {}\n const cards = [\n  ['Open incidents', dashboard.open_incidents, 'Needs attention'],\n  ['Critical', dashboard.critical_incidents, 'Highest severity'],\n  ['Diagnoses', dashboard.total_analyses, 'Failures analyzed'],\n  ['Flaky tests', dashboard.flaky_tests, 'Tracked instability'],\n  ['CI runs', usage.runs || 0, 'Recorded executions'],\n  ['Runner hours', Number(usage.duration_hours || 0).toFixed(1), 'Selected period'],\n  ['Estimated cost', `${Number(usage.estimated_cost || 0).toFixed(2)} ${usage.currency || 'USD'}`, 'Configured rates'],\n  ['Precision', `${Number(feedback.precision_percent || 0).toFixed(1)}%`, 'Confirmed feedback']\n ]\n $('cards').innerHTML = cards.map(item => `<article class=\"metric\"><span>${esc(item[0])}</span><b>${esc(item[1] ?? 0)}</b><small>${esc(item[2])}</small></article>`).join('')\n}\n\nfunction renderOverview(dashboard) {\n renderCards(dashboard)\n const dora = dashboard.dora || {}\n const usage = dashboard.usage || {}\n const doraMetrics = [\n  ['Deployment frequency / day', Number(dora.deployment_frequency_per_day || 0).toFixed(2)],\n  ['Lead time for changes', `${Number(dora.lead_time_for_changes_minutes || 0).toFixed(1)} min`],\n  ['Mean time to restore', `${Number(dora.mean_time_to_restore_minutes || 0).toFixed(1)} min`],\n  ['Change failure rate', `${Number(dora.change_failure_rate_percent || 0).toFixed(1)}%`]\n ]\n $('dora').innerHTML = doraMetrics.map(item => `<span>${esc(item[0])}</span><b>${esc(item[1])}</b>`).join('')\n svgChart('costtrend', dashboard.daily_cost || {}, usage.currency || 'USD')\n svgChart('analysistrend', dashboard.daily_analyses || {})\n svgChart('incidenttrend', dashboard.daily_incidents || {})\n svgChart('testtrend', dashboard.daily_test_failures || {})\n const categories = pairs(dashboard.categories)\n const maximum = Math.max(1, ...categories.map(item => Number(item[1])))\n $('category-bars').innerHTML = categories.map(item => {\n  const share = pct(Number(item[1]) / maximum * 100)\n  return `<div><span>${esc(item[0])}</span><progress max=\"100\" value=\"${share}\" aria-label=\"${esc(item[0])}: ${share}% of the largest category\"></progress><b>${esc(item[1])}</b></div>`\n }).join('') || '<div class=\"chart-empty\">No diagnoses in this period.</div>'\n $('incident-preview').innerHTML = state.incidents.filter(item => item.state !== 'resolved').slice(0, 8).map(incidentRowPreview).join('') || empty(4, 'No active incidents.')\n}\n\nfunction incidentRowPreview(item) {\n return `<tr data-open=\"incident\" data-id=\"${esc(item.fingerprint)}\"><td><b>${esc(item.title)}</b><small>${esc(item.provider)} · ${esc(item.severity)} · ${esc(item.attribution)}</small></td><td>${pill(item.state)}</td><td>${Number(item.repository_count || 0)} repos<small>${Number(item.occurrence_count || 0)} events</small></td><td class=\"actions\">${button('incident-ack', item.fingerprint, 'Acknowledge')}${button('incident-resolve', item.fingerprint, 'Resolve', 'danger')}</td></tr>`\n}\n\nfunction incidentRow(item) {\n return `<tr data-open=\"incident\" data-id=\"${esc(item.fingerprint)}\"><td><b>${esc(item.title)}</b><small>${esc(item.attribution)} · ${esc(item.category || '')}</small></td><td>${esc(item.provider || '—')}</td><td>${pill(item.state)}</td><td>${Number(item.repository_count || 0)}</td><td>${Number(item.occurrence_count || 0)}</td><td>${fmtDate(item.last_seen)}</td><td class=\"actions\">${button('incident-ack', item.fingerprint, 'Acknowledge')}${button('incident-resolve', item.fingerprint, 'Resolve', 'danger')}</td></tr>`\n}\n\nfunction analysisRow(item) {\n return `<tr data-open=\"analysis\" data-id=\"${esc(item.id)}\"><td>${fmtDate(item.created_at)}</td><td><b>${esc(item.repository || 'local')}</b><small>${esc(item.workflow || '')} · ${esc(item.job || '')}</small></td><td>${pill(item.attribution)}<small>${esc(item.category)}</small></td><td class=\"summary\"><b>${esc(item.summary)}</b><small>${esc(item.decision_reason || '')}</small></td><td>${scoreBar(evidenceValue(item))}</td><td class=\"actions\">${button('feedback-correct', item.id, 'Correct')}${button('feedback-partial', item.id, 'Partial')}${button('feedback-incorrect', item.id, 'Wrong', 'danger')}</td></tr>`\n}\n\nfunction testRow(item) {\n const detail = [item.file, item.suite, item.class_name, item.parameters].filter(Boolean).join(' · ')\n return `<tr data-open=\"test\" data-id=\"${esc(item.test_key)}\"><td><b>${esc(item.name)}</b><small>${esc(detail)}</small></td><td>${esc(item.repository)}</td><td>${Number(item.executed_runs || 0)} executed<small>${Number(item.passes || 0)} pass · ${Number(item.failures || 0)} fail · ${Number(item.skipped || 0)} skip</small></td><td>${scoreBar(item.flake_score)}</td><td>${esc(item.primary_flake_cause || 'unknown')}<small>${(Number(item.cause_confidence || 0) * 100).toFixed(0)}% confidence</small></td><td>${pill(item.classification)}${item.quarantined ? '<small>Quarantined</small>' : ''}</td><td class=\"actions\">${item.quarantined ? button('unquarantine', item.test_key, 'Restore') : button('quarantine', item.test_key, 'Quarantine')}</td></tr>`\n}\n\nfunction renderIncidentTable() {\n const query = text($('incident-search').value)\n const filterState = $('incident-state').value\n const filterSeverity = $('incident-severity').value\n const items = state.incidents.filter(item => (!filterState || item.state === filterState) && (!filterSeverity || item.severity === filterSeverity) && (!query || text([item.title, item.provider, item.attribution, item.category, (item.repositories || []).join(' ')].join(' ')).includes(query)))\n $('incident-count').textContent = `${items.length} shown`\n $('incident-table').innerHTML = items.map(incidentRow).join('') || empty(7, 'No incidents match these filters.')\n}\n\nfunction renderAnalysisFilters() {\n const selectedCategory = $('analysis-category').value\n const selectedProvider = $('analysis-provider').value\n const categories = [...new Set(state.analyses.map(item => item.category).filter(Boolean))].sort()\n const providers = [...new Set(state.analyses.map(item => item.provider).filter(Boolean))].sort()\n $('analysis-category').innerHTML = '<option value=\"\">All categories</option>' + categories.map(value => `<option value=\"${esc(value)}\">${esc(value)}</option>`).join('')\n $('analysis-provider').innerHTML = '<option value=\"\">All providers</option>' + providers.map(value => `<option value=\"${esc(value)}\">${esc(value)}</option>`).join('')\n $('analysis-category').value = selectedCategory\n $('analysis-provider').value = selectedProvider\n}\n\nfunction renderAnalysisTable() {\n const query = text($('analysis-search').value)\n const attribution = $('analysis-attribution').value\n const category = $('analysis-category').value\n const provider = $('analysis-provider').value\n const items = state.analyses.filter(item => (!attribution || item.attribution === attribution) && (!category || item.category === category) && (!provider || item.provider === provider) && (!query || text([item.repository, item.workflow, item.job, item.summary, item.decision_reason].join(' ')).includes(query)))\n $('analysis-count').textContent = `${items.length} shown`\n $('analysis-table').innerHTML = items.map(analysisRow).join('') || empty(6, 'No diagnoses match these filters.')\n}\n\nfunction renderTestTable() {\n const query = text($('test-search').value)\n const classification = $('test-state').value\n const cause = $('test-cause').value\n const items = state.tests.filter(item => (!classification || item.classification === classification) && (!cause || item.primary_flake_cause === cause) && (!query || text([item.name, item.repository, item.file, item.suite, item.class_name].join(' ')).includes(query)))\n $('test-count').textContent = `${items.length} shown`\n $('test-table').innerHTML = items.map(testRow).join('') || empty(7, 'No tests match these filters.')\n}\n\nfunction renderOperations() {\n $('repositories').innerHTML = state.repositories.map(item => `<tr><td><b>${esc(item.repository)}</b></td><td>${esc(item.team || item.owner || '—')}</td><td>${pill(item.criticality)}</td><td>${esc((item.notification_channels || []).join(', ') || 'default')}</td></tr>`).join('') || empty(4, 'No repository profiles.')\n $('deliveries').innerHTML = state.deliveries.map(item => `<tr><td>${esc(item.channel)}</td><td>${pill(item.status)}</td><td>${Number(item.attempts || 0)}</td><td>${esc(item.last_error || item.suppressed_reason || '—')}</td></tr>`).join('') || empty(4, 'No notification deliveries.')\n $('provider-count').textContent = `${state.providers.length} configured`\n $('providers').innerHTML = state.providers.map(provider => `<div class=\"provider-row\"><div><b>${esc(provider)}</b><small>Webhook ingestion enabled</small></div></div>`).join('') || '<div class=\"chart-empty\">No provider is configured.</div>'\n}\n\nfunction renderNavigationCounts() {\n $('nav-overview-count').textContent = ''\n $('nav-incident-count').textContent = state.incidents.filter(item => item.state !== 'resolved').length || ''\n $('nav-diagnosis-count').textContent = state.analyses.length || ''\n $('nav-test-count').textContent = state.tests.filter(item => ['flaky', 'suspected_flaky', 'consistently_failing'].includes(item.classification)).length || ''\n $('nav-provider-count').textContent = state.providers.length || ''\n}\n\nfunction switchTab(name) {\n const target = pageMeta[name] ? name : 'overview'\n document.querySelectorAll('.view').forEach(view => view.classList.toggle('active', view.id === target))\n document.querySelectorAll('[data-tab]').forEach(buttonElement => buttonElement.classList.toggle('active', buttonElement.dataset.tab === target))\n $('page-title').textContent = pageMeta[target][0]\n $('page-description').textContent = pageMeta[target][1]\n document.title = `${pageMeta[target][0]} · CI Radar`\n history.replaceState(null, '', `#${target}`)\n}\n\nfunction openDrawer(kind, item) {\n $('drawer-kind').textContent = kind\n $('drawer-title').textContent = item.title || item.summary || item.name || item.id || item.fingerprint\n let body = ''\n if (kind === 'analysis') body = analysisDetail(item)\n if (kind === 'incident') body = incidentDetail(item)\n if (kind === 'test') body = testDetail(item)\n $('drawer-body').innerHTML = body\n $('drawer').classList.add('open')\n $('drawer').setAttribute('aria-hidden', 'false')\n $('backdrop').hidden = false\n}\n\nfunction closeDrawer() {\n $('drawer').classList.remove('open')\n $('drawer').setAttribute('aria-hidden', 'true')\n $('backdrop').hidden = true\n}\n\nfunction keyValues(values) {\n return `<dl>${values.filter(item => item[1] !== undefined && item[1] !== null && item[1] !== '').map(item => `<dt>${esc(item[0])}</dt><dd>${esc(item[1])}</dd>`).join('')}</dl>`\n}\n\nfunction analysisDetail(item) {\n const evidence = (item.human_evidence || []).map(value => `<li>${esc(value)}</li>`).join('') || '<li>No evidence list recorded.</li>'\n const actions = (item.suggested_actions || []).map(action => `<article class=\"recommendation\"><header><b>${esc(action.title)}</b>${pill(action.risk)}</header><p>${esc(action.description || '')}</p><small>${esc(action.type || '')}</small></article>`).join('') || '<p>No recommended action was recorded.</p>'\n const values = [\n  ['Repository', item.repository],\n  ['Workflow', item.workflow],\n  ['Job', item.job],\n  ['Provider', item.provider],\n  ['Category', item.category],\n  ['Attribution', item.attribution],\n  ['Evidence strength', evidenceValue(item)],\n  ['Externality score', externalityValue(item)],\n  ['External evidence', item.external_evidence_score],\n  ['Code evidence', item.code_evidence_score],\n  ['Fingerprint', item.fingerprint],\n  ['Created', fmtDate(item.created_at)]\n ]\n return `${keyValues(values)}<h3>Evidence</h3><ul class=\"evidence\">${evidence}</ul><h3>Decision</h3><p>${esc(item.decision_reason || item.summary)}</p><h3>Redacted excerpt</h3><pre>${esc(item.excerpt || item.redacted_excerpt || 'Raw logs are not stored by default.')}</pre><h3>Recommended actions</h3>${actions}<div class=\"drawer-actions\">${button('github-issue', item.id, 'Open GitHub issue')}</div>`\n}\n\nfunction incidentDetail(item) {\n const values = [\n  ['Provider', item.provider],\n  ['Category', item.category],\n  ['Attribution', item.attribution],\n  ['Severity', item.severity],\n  ['State', item.state],\n  ['Repositories', item.repository_count],\n  ['Occurrences', item.occurrence_count],\n  ['First seen', fmtDate(item.first_seen)],\n  ['Last seen', fmtDate(item.last_seen)],\n  ['Fingerprint', item.fingerprint]\n ]\n const repositories = (item.repositories || []).map(repository => `<li>${esc(repository)}</li>`).join('') || '<li>Not recorded.</li>'\n return `${keyValues(values)}<h3>Affected repositories</h3><ul class=\"evidence\">${repositories}</ul><div class=\"drawer-actions\">${button('incident-ack', item.fingerprint, 'Acknowledge')}${button('incident-resolve', item.fingerprint, 'Resolve', 'danger')}</div>`\n}\n\nfunction testDetail(item) {\n const values = [\n  ['Repository', item.repository],\n  ['Framework', item.framework],\n  ['File', item.file],\n  ['Suite', item.suite],\n  ['Class', item.class_name],\n  ['Observations', item.total_runs],\n  ['Executed', item.executed_runs],\n  ['Skipped', item.skipped],\n  ['Passes', item.passes],\n  ['Failures', item.failures],\n  ['Failure rate', `${(Number(item.failure_rate || 0) * 100).toFixed(1)}%`],\n  ['95% interval', `${(Number(item.failure_rate_low || 0) * 100).toFixed(1)}–${(Number(item.failure_rate_high || 0) * 100).toFixed(1)}%`],\n  ['History confidence', `${(Number(item.history_confidence || 0) * 100).toFixed(0)}%`],\n  ['Rerun recoveries', item.rerun_recoveries],\n  ['Compute minutes lost', Number(item.estimated_compute_minutes_lost || 0).toFixed(1)],\n  ['Engineering minutes lost', Number(item.estimated_engineering_minutes_lost || 0).toFixed(1)],\n  ['Flake score', Number(item.flake_score || 0).toFixed(1)],\n  ['Flake probability', Number(item.flake_probability || 0).toFixed(1)],\n  ['Classification', item.classification],\n  ['Likely cause', item.primary_flake_cause],\n  ['Cause confidence', `${(Number(item.cause_confidence || 0) * 100).toFixed(0)}%`],\n  ['Last seen', fmtDate(item.last_seen)]\n ]\n const status = item.quarantined ? 'This test is currently quarantined.' : 'This test blocks CI when it fails.'\n const action = item.quarantined ? button('unquarantine', item.test_key, 'Restore test') : button('quarantine', item.test_key, 'Quarantine test')\n return `${keyValues(values)}<h3>Quarantine</h3><p>${status}</p><div class=\"drawer-actions\">${action}</div>`\n}\n\nfunction fieldMarkup(field) {\n const required = field.required ? ' required' : ''\n if (field.type === 'select') {\n  const options = field.options.map(option => `<option value=\"${esc(option.value)}\"${option.value === field.value ? ' selected' : ''}>${esc(option.label)}</option>`).join('')\n  return `<label>${esc(field.label)}<select name=\"${esc(field.name)}\"${required}>${options}</select></label>`\n }\n if (field.type === 'textarea') {\n  return `<label>${esc(field.label)}<textarea name=\"${esc(field.name)}\"${required}>${esc(field.value || '')}</textarea></label>`\n }\n return `<label>${esc(field.label)}<input name=\"${esc(field.name)}\" type=\"${esc(field.type || 'text')}\" value=\"${esc(field.value || '')}\"${required}></label>`\n}\n\nfunction openActionDialog(config) {\n actionContext = config\n $('action-kind').textContent = config.kind || 'Action'\n $('action-title').textContent = config.title\n $('action-description').textContent = config.description || ''\n $('action-submit').textContent = config.submitLabel || 'Save'\n $('action-fields').innerHTML = (config.fields || []).map(fieldMarkup).join('')\n $('action-dialog').showModal()\n const first = $('action-fields').querySelector('input,select,textarea')\n if (first) first.focus()\n}\n\nfunction closeActionDialog() {\n actionContext = null\n $('action-dialog').close()\n}\n\nasync function submitAction(event) {\n event.preventDefault()\n if (!actionContext) return\n const formData = new FormData(event.currentTarget)\n const values = Object.fromEntries(formData.entries())\n $('action-submit').disabled = true\n try {\n  await actionContext.submit(values)\n  closeActionDialog()\n  closeDrawer()\n  await load(true)\n } catch (error) {\n  setError(error.message)\n } finally {\n  $('action-submit').disabled = false\n }\n}\n\nasync function load(force = false) {\n if (state.loading && !force) return\n setLoading(true)\n setError()\n try {\n  const range = encodeURIComponent($('range').value)\n  const [dashboard, repositories, deliveries, tests, analyses, incidents, status] = await Promise.all([\n   api(`/api/v1/dashboard?range=${range}`),\n   api('/api/v1/repositories'),\n   api('/api/v1/notifications/deliveries?limit=100'),\n   api('/api/v1/tests?limit=500'),\n   api('/api/v1/analyses?limit=500'),\n   api('/api/v1/incidents?limit=500'),\n   api('/api/v1/status')\n  ])\n  state.dashboard = dashboard\n  state.repositories = repositories.repositories || []\n  state.deliveries = deliveries.deliveries || []\n  state.tests = tests.tests || []\n  state.analyses = analyses.analyses || analyses || []\n  state.incidents = incidents.incidents || incidents || []\n  state.providers = status.connectors_enabled || []\n  renderOverview(dashboard)\n  renderIncidentTable()\n  renderAnalysisFilters()\n  renderAnalysisTable()\n  renderTestTable()\n  renderOperations()\n  renderNavigationCounts()\n  $('updated-at').textContent = `Updated ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`\n  setConnection('Connected', 'online')\n } catch (error) {\n  const message = error.status === 401 ? 'Sign in with an admin token, API key or SSO to load this dashboard.' : error.message\n  setError(message)\n  setConnection('Unavailable', 'offline')\n  if (error.status === 401) $('session-panel')?.setAttribute('open', '')\n } finally {\n  setLoading(false)\n }\n}\n\nasync function incidentState(id, action) {\n await api(`/api/v1/incidents/${encodeURIComponent(id)}/${action}`, { method: 'POST', body: '{}' })\n closeDrawer()\n await load(true)\n}\n\nasync function feedback(id, verdict) {\n if (verdict !== 'incorrect') {\n  await api(`/api/v1/analyses/${encodeURIComponent(id)}/feedback`, {\n   method: 'POST',\n   body: JSON.stringify({ verdict })\n  })\n  await load(true)\n  return\n }\n openActionDialog({\n  kind: 'Diagnosis feedback',\n  title: 'Mark diagnosis as wrong',\n  description: 'Select the cause that should have been assigned.',\n  submitLabel: 'Submit feedback',\n  fields: [{\n   name: 'actual_cause',\n   label: 'Actual cause',\n   type: 'select',\n   value: 'CODE',\n   required: true,\n   options: ['EXTERNAL', 'CODE', 'MIXED', 'TOOLCHAIN', 'UNKNOWN'].map(value => ({ value, label: value }))\n  }],\n  submit: values => api(`/api/v1/analyses/${encodeURIComponent(id)}/feedback`, {\n   method: 'POST',\n   body: JSON.stringify({ verdict, actual_cause: values.actual_cause })\n  })\n })\n}\n\nfunction quarantine(key) {\n openActionDialog({\n  kind: 'Test quarantine',\n  title: 'Quarantine test',\n  description: 'Keep the owner and reason specific so the quarantine can be reviewed.',\n  submitLabel: 'Quarantine',\n  fields: [\n   { name: 'owner', label: 'Owner', value: 'platform', required: true },\n   { name: 'reason', label: 'Reason', type: 'textarea', value: 'Known flaky test under investigation', required: true },\n   { name: 'days', label: 'Expires after days', type: 'number', value: '7', required: true }\n  ],\n  submit: values => {\n   const days = Math.max(1, Math.min(365, Number(values.days) || 7))\n   return api(`/api/v1/tests/${encodeURIComponent(key)}/quarantine`, {\n    method: 'POST',\n    body: JSON.stringify({\n     owner: values.owner,\n     reason: values.reason,\n     expires_at: new Date(Date.now() + days * 864e5).toISOString()\n    })\n   })\n  }\n })\n}\n\nasync function unquarantine(key) {\n await api(`/api/v1/tests/${encodeURIComponent(key)}/quarantine`, { method: 'DELETE' })\n closeDrawer()\n await load(true)\n}\n\nasync function githubIssue(id) {\n let result\n try {\n  result = await api(`/api/v1/analyses/${encodeURIComponent(id)}/github-issue`)\n } catch (error) {\n  if (error.status !== 404) throw error\n  result = await api(`/api/v1/analyses/${encodeURIComponent(id)}/github-issue`, { method: 'POST', body: '{}' })\n }\n const url = result?.issue?.html_url || result?.link?.url\n if (url) window.open(url, '_blank', 'noopener,noreferrer')\n}\n\nasync function act(buttonElement) {\n const action = buttonElement.dataset.action\n const id = buttonElement.dataset.id\n if (action === 'incident-ack') return incidentState(id, 'acknowledge')\n if (action === 'incident-resolve') return incidentState(id, 'resolve')\n if (action === 'feedback-correct') return feedback(id, 'correct')\n if (action === 'feedback-partial') return feedback(id, 'partial')\n if (action === 'feedback-incorrect') return feedback(id, 'incorrect')\n if (action === 'quarantine') return quarantine(id)\n if (action === 'unquarantine') return unquarantine(id)\n if (action === 'github-issue') return githubIssue(id)\n}\n\nfunction handleOpen(row) {\n const kind = row.dataset.open\n const id = row.dataset.id\n if (kind === 'analysis') {\n  const item = state.analyses.find(value => value.id === id)\n  if (item) openDrawer(kind, item)\n }\n if (kind === 'incident') {\n  const item = state.incidents.find(value => value.fingerprint === id)\n  if (item) openDrawer(kind, item)\n }\n if (kind === 'test') {\n  const item = state.tests.find(value => value.test_key === id)\n  if (item) openDrawer(kind, item)\n }\n}\n\ndocument.addEventListener('click', event => {\n const action = event.target.closest('button[data-action]')\n if (action) {\n  event.stopPropagation()\n  act(action).catch(error => setError(error.message))\n  return\n }\n const tab = event.target.closest('[data-tab]')\n if (tab) {\n  switchTab(tab.dataset.tab)\n  return\n }\n const jump = event.target.closest('[data-tab-jump]')\n if (jump) {\n  switchTab(jump.dataset.tabJump)\n  return\n }\n const row = event.target.closest('tr[data-open]')\n if (row) handleOpen(row)\n})\n\nfor (const id of ['incident-search', 'incident-state', 'incident-severity']) $(id).addEventListener('input', renderIncidentTable)\nfor (const id of ['analysis-search', 'analysis-attribution', 'analysis-category', 'analysis-provider']) $(id).addEventListener('input', renderAnalysisTable)\nfor (const id of ['test-search', 'test-state', 'test-cause']) $(id).addEventListener('input', renderTestTable)\n\n$('drawer-close').addEventListener('click', closeDrawer)\n$('backdrop').addEventListener('click', closeDrawer)\n$('action-close').addEventListener('click', closeActionDialog)\n$('action-cancel').addEventListener('click', closeActionDialog)\n$('action-form').addEventListener('submit', submitAction)\n$('secure-login').addEventListener('click', () => secureLogin().catch(error => setError(error.message)))\n$('sso-login').addEventListener('click', () => location.assign('/auth/login?return_to=/'))\n$('logout').addEventListener('click', () => location.assign('/auth/logout'))\n$('refresh').addEventListener('click', () => load(true))\n$('range').addEventListener('change', () => load(true))\n\nwindow.addEventListener('keydown', event => {\n if (event.key === 'Escape' && !$('action-dialog').open) closeDrawer()\n})\n\ndocument.addEventListener('visibilitychange', () => {\n if (!document.hidden) load()\n})\n\nswitchTab(location.hash.slice(1) || 'overview')\nsetInterval(() => {\n if (!document.hidden) load()\n}, 30000)\nload()\n"
